        var roles = O(info["roles"]);
        var paths = roles.TryGetValue(role, out var pv) ? Strs(pv) : new L();
        if (paths.Count != 1) return null;
        foreach (var p in A(decl["params"])) if (S(O(p)["path"]) == S(paths[0])) return (O(p)["path"], O(p)["ty"]);
        return null;
    }
    static M? XTerm(M ont, M cat, string verb, M t)
    {
