            case "cmp": { var l = XTerm(ont, cat, verb, O(c["l"])); var r = XTerm(ont, cat, verb, O(c["r"])); return l == null || r == null ? null : Mk("k", "cmp", "op", c["op"], "l", l, "r", r); }
            case "and": case "or": { var a = XCond(ont, cat, verb, O(c["a"])); var b = XCond(ont, cat, verb, O(c["b"])); return a == null || b == null ? null : Mk("k", c["k"], "a", a, "b", b); }
            default: { var a = XCond(ont, cat, verb, O(c["c"])); return a == null ? null : Mk("k", "not", "c", a); }
        }
    }
    static M? BoundValue(M ont, M cat, L vs, M t)
    {
        if (S(t["k"]) != "role") return t;
        var rs = new List<(object?, object?)>();
        foreach (var v in vs) { var r = ResolveRole(ont, cat, S(v), S(t["role"])); if (r == null) return null; rs.Add(r.Value); }
        if (rs.Count == 0) return null;
        bool same = rs.All(r => S(r.Item1) == S(rs[0].Item1) && Canon(r.Item2) == Canon(rs[0].Item2));
        bool sameTy = rs.All(r => Canon(r.Item2) == Canon(rs[0].Item2));
        if (same) return Mk("k", "param", "path", rs[0].Item1, "ty", rs[0].Item2);
        if (sameTy) return Mk("k", "param", "path", "@" + S(t["role"]), "ty", rs[0].Item2);
        return null;
    }
    static M ExpandSel(M sg, M ont, M cat)
    {
        var es = new List<(object?, M)>();
        foreach (var gg in A(sg["grants"]))
        {
            var gr = O(gg); var s = O(gr["sel"]);
            var verbs = S(s["k"]) == "verb" ? new L { s["verb"] } : ClassVerbs(cat, Strs(s["all_of"]), Strs(s["none_of"]), false);
            foreach (var v in verbs)
            {
                var c = XCond(ont, cat, S(v), O(gr["cond"]));
                if (c == null) continue;
                es.Add((gr["gid"], Mk("gid", S(s["k"]) == "class" ? S(gr["gid"]) + "." + S(v) : gr["gid"], "verb", v, "res", gr["res"], "cond", c)));
            }
        }
        L IdsOf(L srcs) => Ls(es.Where(e => Has(srcs, e.Item1)).Select(e => e.Item2["gid"]));
        L GidsOfVerbs(L vs) => Ls(es.Where(e => Has(vs, e.Item2["verb"])).Select(e => e.Item2["gid"]));
        L VerbsOfGids(L g) => Ls(es.Where(e => Has(g, e.Item2["gid"])).Select(e => e.Item2["verb"]));
        var prohibits = new L();
        foreach (var pp in A(sg["prohibits"]))
        {
            var p = O(pp); var t = O(p["target"]); var tk = S(t["k"]);
            var verbs = tk == "verb" ? new L { t["verb"] } : tk == "effect" ? VerbsOfClass(ont, S(t["cls"])) : ClassVerbs(cat, Strs(t["all_of"]), Strs(t["none_of"]), true);
            foreach (var v in verbs)
            {
                var c = XCond(ont, cat, S(v), O(p["cond"])) ?? Mk("k", "true");
                prohibits.Add(Mk("pid", tk == "verb" ? p["pid"] : S(p["pid"]) + "." + S(v), "target", Mk("k", "verb", "verb", v), "res", p["res"], "cond", c));
            }
        }
        var bounds = new L();
        foreach (var bb in A(sg["bounds"]))
        {
            var b = O(bb); var s = O(b["sel"]); var sk = S(s["k"]);
            L? gids; L rv;
            if (sk == "gids") { gids = IdsOf(Strs(s["gids"])); rv = VerbsOfGids(gids); }
            else if (sk == "effect") { gids = null; rv = VerbsOfClass(ont, S(s["cls"])); }
            else { gids = GidsOfVerbs(ClassVerbs(cat, Strs(s["all_of"]), Strs(s["none_of"]), true)); rv = VerbsOfGids(gids); }
            var val = BoundValue(ont, cat, rv, O(b["value"]));
            if (val == null || (gids != null && gids.Count == 0)) continue;
            var sel = gids == null ? Mk("k", "effect", "cls", s["cls"]) : Mk("k", "gids", "gids", gids);
            bounds.Add(Mk("bid", b["bid"], "sel", sel, "agg", b["agg"], "value", val, "key", b["key"], "window", b["window"], "scope", b["scope"], "cap", b["cap"], "onExceed", b["onExceed"]));
        }
        var holes = Ls(A(sg["holes"]).Select(hh => (object?)With(O(hh), "affects", IdsOf(Strs(O(hh)["affects"])))));
        return Mk("v", 1L, "principal", sg["principal"], "ontDigest", sg["ontDigest"], "nlDigest", sg["nlDigest"], "sources", sg["sources"],
            "grants", Ls(es.Select(e => (object?)e.Item2)), "prohibits", prohibits, "bounds", bounds, "validity", sg["validity"],
            "deleg", With(O(sg["deleg"]), "mayTouch", IdsOf(Strs(O(sg["deleg"])["mayTouch"]))), "escalateOn", sg["escalateOn"],
            "wildcardAck", IdsOf(Strs(sg["wildcardAck"])), "holes", holes);
    }

    // ---------------------------------------------------------------- fn vectors
    static readonly Dictionary<string, int> Rank = new() { ["deny"] = 0, ["escalate"] = 1, ["allow"] = 2 };
    public static string Meet(string d, string s) => Rank.TryGetValue(s, out var r) && r < Rank[d] ? s : d;
    static void Walk(M c, SortedSet<string> o)
    {
        switch (S(c["k"]))
        {
            case "and": case "or": Walk(O(c["a"]), o); Walk(O(c["b"]), o); break;
            case "not": Walk(O(c["c"]), o); break;
            case "cmp":
                foreach (var k in new[] { "l", "r" }) { var t = O(c[k]); if (S(t["k"]) == "param") foreach (var p in new[] { "env.class.", "env.prov.", "env.judge.", "env.world." }) if (S(t["path"]).StartsWith(p, StringComparison.Ordinal)) o.Add(S(t["path"])); }
                break;
        }
    }
    static object? RunFn(M v)
    {
        var i = v["input"];
        switch (S(v["fn"]))
        {
            case "canon": return Mk("canon", Canon(i), "digest", GoalDigest(i));
            case "units":
                {
                    var sc = O(O(i)["schema"]); var tm = O(O(i)["terms"]);
                    var bad = tm.Keys.Where(p => !sc.ContainsKey(p) || Canon(sc[p]) != Canon(tm[p])).ToList(); bad.Sort(Cmp);
                    return Ls(bad.Select(x => (object?)x));
                }
            case "polarity": { var o = new SortedSet<string>(Comparer<string>.Create(Cmp)); foreach (var w in A(i)) Walk(O(w), o); return Ls(o.Select(x => (object?)x)); }
            case "meet": return Meet(S(O(i)["decision"]), S(O(i)["signal"]));
            case "pep":
                {
                    var d = S(O(i)["decision"]);
                    if (d == "allow") return true;
                    if (d == "deny") return false;
                    var ans = O(i)["answer"] as M; var ctx = O(O(i)["ctx"]);
                    if (ans == null || ans["valid"] is not true) return false;
                    foreach (var k in new[] { "policy_digest", "action_digest", "history_head" }) if (S(ans[k]) != S(ctx[k])) return false;
                    return true;
                }
            case "commit": return Mk("commit", B64(Sha("pca-goal:v3:commit:" + S(O(i)["goal_digest"]) + ":" + S(O(i)["policy_digest"]) + ":" + S(O(i)["salt"]))), "opens_other_goal", false);
            case "claim": { var rp = O(i)["replayed_ppm"]; return rp != null && N(rp) < N(O(i)["min_ppm"]) ? Meet(S(O(i)["base"]), "escalate") : O(i)["base"]; }
            default: throw new InvalidOperationException("unknown fn " + v["fn"]);
        }
    }

    /// <summary>Replays every vector of a directory: (vectors, probes, disagreements).</summary>
    public static (int, int, List<string>) Replay(string d)
    {
        var names = Directory.GetFiles(d, "*.json").Select(Path.GetFileName).Where(n => n != "index.json").Select(n => n!).ToList(); names.Sort(string.CompareOrdinal);
        var bad = new List<string>(); int probes = 0;
        foreach (var n in names)
        {
            using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(d, n), Encoding.UTF8));
            var v = O(Conv(doc.RootElement)); var id = S(v["id"]);
            if (S(v["kind"]) == "fn") { if (Canon(RunFn(v)) != Canon(v["expect"])) bad.Add(id); continue; }
            var goal = O(v["goal"]); var ont = O(v["ontology"]);
            if (v.TryGetValue("sel", out var sel) && sel != null && Canon(ExpandSel(O(O(sel)["goal"]), ont, O(O(sel)["catalog"]))) != Canon(goal)) bad.Add(id + ":expansion");
            if (GoalDigest(goal) != S(v["goal_digest"])) bad.Add(id + ":goal_digest");
            if (O(v["compile"])["ok"] is not true) continue;
            if (HashCanon(Lower(ont, goal)) != S(v["policy_digest"])) bad.Add(id + ":policy_digest");
            var ps = A(v["probes"]);
            for (int i = 0; i < ps.Count; i++)
            {
                probes++; var p = O(ps[i]);
                if (Canon(Decide(goal, ont, O(p["action"]), O(p["history"]))) != Canon(p["expect"])) bad.Add(id + "#" + i);
            }
        }
        return (names.Count, probes, bad);
    }

    public static int Run(string[] args)
    {
        var (n, probes, bad) = Replay(args[0]);
        Console.WriteLine($"dotnet: {n} vectors, {probes} probes, {bad.Count} disagreements");
        foreach (var b in bad.Take(20)) Console.WriteLine("   " + b);
        return bad.Count > 0 || n == 0 ? 1 : 0;
    }
}
